{"implementation":"def solve(case):
    payload = case["payload"]
    threshold = payload["threshold"]
    calls = payload["calls"]
    accepted_ids = []
    diagnostics = []
    for call in calls:
        if not all(k in call for k in ("call_id","loss_without_call","loss_with_call","prediction_tokens","parseable")):
            continue
        if not call["parseable"]:
            continue
        gain = call["loss_without_call"] - call["loss_with_call"]
        tokens = call["prediction_tokens"]
        if tokens < 1:
            continue
        norm_gain = gain / tokens
        if norm_gain >= threshold:
            accepted_ids.append(call["call_id"])
            diagnostics.append({
                "call_id": call["call_id"],
                "normalized_gain": round(norm_gain, 4)
            })
    return {
        "accepted_call_ids": accepted_ids,
        "diagnostics": diagnostics
    }"}
